scwin.gKeyword;

// DisclosureSearchAppImpl.java 에서 사용중. vScrenID바꾸지 마세요 20170421

///////// 2. 초기화 영역 /////////
scwin.onpageload = async function() {
    try {
        // MxDataSet_com_isur.setJSON([{"SPOT_ISU_TRD_MKT_TP_CD":"","COM_ABBRV":"a","ISUR_CD":"1","LIST_STAT_CD":"aa","rowStatus":"R"},{"SPOT_ISU_TRD_MKT_TP_CD":"","COM_ABBRV":"b","ISUR_CD":"2","LIST_STAT_CD":"bb","rowStatus":"R"},{"SPOT_ISU_TRD_MKT_TP_CD":"","COM_ABBRV":"c","ISUR_CD":"3","LIST_STAT_CD":"cc","rowStatus":"R"},{"SPOT_ISU_TRD_MKT_TP_CD":"","COM_ABBRV":"d","ISUR_CD":"4","LIST_STAT_CD":"dd","rowStatus":"R"},{"SPOT_ISU_TRD_MKT_TP_CD":"","COM_ABBRV":"","ISUR_CD":"","LIST_STAT_CD":"","rowStatus":"C"},{"SPOT_ISU_TRD_MKT_TP_CD":"","COM_ABBRV":"","ISUR_CD":"","LIST_STAT_CD":"","rowStatus":"C"},{"SPOT_ISU_TRD_MKT_TP_CD":"","COM_ABBRV":"","ISUR_CD":"","LIST_STAT_CD":"","rowStatus":"C"},{"SPOT_ISU_TRD_MKT_TP_CD":"","COM_ABBRV":"","ISUR_CD":"","LIST_STAT_CD":"","rowStatus":"C"}]);

        grd_Grid_excel.hide();
        //// $c.stf.showObj(mgrd_Grid_excel, false);
        panel_scn.hide();
        panel_combo.hide();
        mgrd_Grid.hide();
        txb_FssUnqNo.hide();

        scwin.setCode();

        const codeOptions = [ 
            { code : "sndloc_tp_cd", compID : "cmb_TeamList" },  // 송신처구분코드
            { code : "discls_kind_cd", compID : "cmb_EmpList" } // 공시종류코드
        ]; 
        // await $c.data.setCommonCode(codeOptions); 
        $c.stf.comboCbDataSetLimit(cmb_PerPage);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        await scwin.checkCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15000.onpageload" });
    }
};

scwin.onpageunload = function() {

};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.btn_Search_onclick = function() {
    try {
        scwin.checkCond();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.btn_Search_onclick" });
    }
};

scwin.cmb_PerPage_OnCloseUp = function() {
    try {
        const vPerPage = $c.cp.valueOfIndex(cmb_PerPage, "VALUE", cmb_PerPage.getSelectedIndex());
        scwin.pageSize = vPerPage;
        // $c.win.alert(pageSize);	
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.cmb_PerPage_OnCloseUp" });
    }
};

scwin.dts_scn_list_OnLoadError = function() {
    try {
        $c.win.alert('dts_scn_list.OnLoadError() ' + dts_scn_list.errorMsg);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.dts_scn_list_OnLoadError" });
    }
};

scwin.dts_DsclList_OnLoadError = function() {
    try {
        $c.win.alert("OnLoadError => " + dts_DsclList);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.dts_DsclList_OnLoadError" });
    }
};

scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    try {
        ////showload.style.display = "none";

        // 채권일경우 상장 제외 20170310
        if (rdo_MKT_ID.getValue() === "4") {
            $c.cp.setColumnProp(grd_Grid, "LIST_STAT_ID", 'Show', false);
            $c.cp.setColumnProp(grd_Grid, "COM_ABBRV", 'color', "Black");
        } else {
            $c.cp.setColumnProp(grd_Grid, "LIST_STAT_ID", 'Show', true);
        }
        if (dts_DsclList.errorMsg) {
            $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
        } else {
            /*	
            //수정해야될 부분
            //데이터가 로드 되면 다음 내용을 처리 하도록 한다.
            //최초 조회인 경우 전체 row cnt를 구한다.		
            if (vCurrPageNo == 0){
            	vCurrPageNo = 1;
            	totalCnt = dts_DsclList.NameString(0,"TOTALCNT");			
            }
            */
            if (scwin.pageSize !== '0') {
                if (scwin.vCurrPageNo === 0) {
                    scwin.vCurrPageNo = 1;
                    scwin.totalCnt = dts_DsclList.getCellData(0, "TOTALCNT");
                }
            } else {
                scwin.totalCnt = rowcount;
            }
            // $c.win.alert(pageNoCnt +", "+pageSize+", "+totalCnt);
            // 페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
            $c.stf.FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 743);
        }

        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_Search.setDisabled(false);
        ////btn_Search.src = "../img/btn_select.gif";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.dts_DsclList_OnLoadCompleted" });
    }
};

scwin.dts_scn_list_OnLoadCompleted = function(rowcount) {
    try {
        let combo_text = "";
        for (let i = 0; i <= dts_scn_list.getRowCount() - 1; i++) {
            combo_text += $c.cp.valueOfIndex(cmb_scn_list, "TEXT", i) + ",";
        }
        panel_combo.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='16' width='100%'>" + "    <tr>" + "        <td align='left'  nowrap style='font-size__9pt; font-family:굴림;'>" + $c.stf.replaceAll(combo_text.substring(0, combo_text.lastIndexOf(',')), " ", "") + "</td>";
        "    </tr>" + "</table>";

        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        // btn_Search.disabled = false;
        // btn_Search.src = "../img/btn_select.gif";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.dts_scn_list_OnLoadCompleted" });
    }
};

scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // setObjectValue(cmb_EmpList, $c.session.info("js_emp_no"));	

};

scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "UPTEAM" ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.dts_emp_OnFilter" });
    }
};

scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        if (js_dep_cd.substring(0, 2) === '26' || $c.session.info("js_dep_cd").substring(0, 2) === '34') {
            $c.stf.copyDataSet(dts_dep, dts_dep1);
            scwin.addDsclTeamAll(rowcount);
            cmb_TeamList.setValue('UPTEAM');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.dts_dep_OnLoadCompleted" });
    }
};

scwin.dts_DsclList_excel_OnLoadError = function() {
    try {
        $c.win.alert("엑셀저장에 실패하였습니다. : " + dts_DsclList_excel);
        showload.style.display = "none";
        btn_Excel.setDisabled(false);
        btn_Excel.setBackgroundImage("../img/btn_excelsave.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.dts_DsclList_excel_OnLoadError" });
    }
};

scwin.dts_DsclList_excel_OnLoadCompleted = function(rowcount) {
    try {
        showload.style.display = "none";
        if (scwin.gExcelTp === "1") {
            // 채권일경우 상장 제외 20170310
            if (rdo_MKT_ID.getValue() === "4") {
                $c.cp.setColumnProp(grd_Grid_excel, "LIST_STAT_ID", 'Show', false);
                $c.cp.setColumnProp(grd_Grid_excel, "COM_ABBRV", 'color', "Black");
            }
            $c.data.downloadGridViewExcel(grd_Grid_excel, {fileName: "공시상세검색  목록", type: "8"});
        } else {
            const responseCode = dts_DsclList_excel.getCellData(1, "VALUE");
            const inside_email = dts_DsclList_excel.getCellData(1, "TEXT");
            if (responseCode === "200") {
                $c.win.alert("1만건 이상은 메일로 제공합니다.\n엑셀저장이 완료되면 등록된 이메일(" + inside_email + ")로 엑셀파일 링크가 전송됩니다.\n(5만건 기준 약 1분 소요).");
            } else {
                $c.win.alert("엑셀저장에 실패하였습니다. [" + responseCode + "]");
            }
        }

        // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_Excel.setDisabled(false);
        btn_Excel.setBackgroundImage("../img/btn_excelsave.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.dts_DsclList_excel_OnLoadCompleted" });
    }
};

scwin.grd_Grid_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "DOC_TITLE") {
            $c.stf.openDisclViewer(scwin.gAcptNo, "R");
        } else if (colid === "ACPT_DDTM") {
            $c.stf.openDisclAllList();
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.grd_Grid_OnDblClick" });
    }
};

scwin.mgrd_Grid_OnLButtonDblClk = function(type, row, colid, x, y) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "DOC_TITLE") {
            $c.stf.openDisclViewer(scwin.gAcptNo, "R");
        } else if (colid === "ACPT_DDTM") {
            $c.stf.openDisclAllList();
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15000.mgrd_Grid_OnLButtonDblClk" });
    }
};

