scwin.resetParam = function() {
    vCurrDate = $c.utils.cGetToday("yyyymmdd"); // 현재날짜

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.
    if ($c.session.info("js_dep_cd").substring(0, 2) === '26' || $c.session.info("js_dep_cd").substring(0, 2) === '34') {
        scwin.gDepCd = "UPTEAM";
        cmb_TeamList.setValue(scwin.gDepCd);
    }

    // 코넥스 추가를 추가 했었지만 2017.02.17 모든 시장을 보여달라고 해서 삭제함
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
    } else {
        // 코넥스는 유가, 코스닥도 볼 수 있음
        if (scwin.gLdMktTp === '6' || scwin.gLdMktTp === '4') {
            rdo_MKT_ID.setValue(scwin.gLdMktTp);
        } else {
            rdo_MKT_ID.setValue('9');
        }
    }

    // 채권일 경우 채권상장폐지여부 제외 항목으로 보이게끔 수정 20170310
    if (rdo_MKT_ID.getValue() === '4') {
        label_3.hide();
        label_24.show("");
        scwin.setChkValue(chb_ListStatCd, "1");
    } else {
        label_3.show("");
        label_24.hide();
        scwin.setChkValue(chb_ListStatCd, false);
    }

    // setObjectValue(rdo_MKT_ID, $c.session.info("js_market"));

    txb_isur_cd.setValue("");
    txb_com_abbrv.setValue("");
    edt_FromDate.setValue(vCurrDate);
    edt_ToDate.setValue(vCurrDate);
    cmb_EmpList.setValue("");
    // setChkValue(chb_ListStatCd, false);
    scwin.setChkValue(chb_Last, false);
    scwin.setChkValue(chb_ByPass, false);
    txb_FormCd.setValue("");
    txb_FormNm.setValue("");
    txb_keyword.setValue("");
    txb_FssUnqNo.setValue("");
    txb_FssUnqNm.setValue("");
    cmb_month.setValue("");
    cmb_IndTp.setValue("");
    scwin.setChkValue(chb_kor_yn, true);
    scwin.setChkValue(chb_eng_yn, true);
    scwin.setChkValue(chb_main_yn, true);
    scwin.setChkValue(chb_atch_yn, true);
    scwin.setChkValue(chb_dep_tp, true);
    cmb_Basis.setValue("2");
    cmb_PerPage.setValue("50");
    txb_rsn_cnt.setValue("");
    dts_Dscl_Cond.removeAll();
    scwin.gRsnClssCdList = "";
};

// 공시팀 전체 목록에 추가
scwin.addDsclTeamAll = function(rowcount, dtsDepComp, dtsDepCompCopy) {
    dtsDepComp.setCellData(2,"VALUE", 'UPTEAM');		// 
    dtsDepComp.setCellData(2,"TEXT", '공시팀 전체');
    dtsDepComp.setCellData(2,"DEP_CD", 'UPTEAM' );		
    for (let i = 3; i <= rowcount; i++) {
        dtsDepComp.setCellData(i,"VALUE", dtsDepCompCopy.getCellData(i-1,"VALUE"));		// 
        dtsDepComp.setCellData(i,"TEXT", dtsDepCompCopy.getCellData(i-1,"TEXT"));	
        dtsDepComp.setCellData(i,"DEP_CD", dtsDepCompCopy.getCellData(i-1,"DEP_CD"));
    }
    dtsDepComp.insertRow();
    dtsDepComp.setCellData(rowcount+1,"VALUE", dtsDepCompCopy.getCellData(rowcount,"VALUE"));		// 
    dtsDepComp.setCellData(rowcount+1,"TEXT", dtsDepCompCopy.getCellData(rowcount,"TEXT"));	
    dtsDepComp.setCellData(rowcount+1,"DEP_CD", dtsDepCompCopy.getCellData(rowcount,"DEP_CD"));	
};

// 첨부서류만 선택하고 본문검색을 하고자할때 알림.
scwin.chkAttchKeyword = function() {
    let vKeyword = txb_keyword.getValue();
    if (vKeyword.length > 0) {
        if (scwin.getChkValue(chb_main_yn) === 0 &&
            scwin.getChkValue(chb_atch_yn) === 1) {
            $c.win.alert('첨부서류만 선택한 후에는 공시본문내용 검색기능을 사용 할 수 없습니다.\n공시본문에서만 내용검색이 가능합니다.');
            txb_keyword.focus();
            return false;
        }
    }
};
